DO $$ DECLARE d text; BEGIN SELECT pg_get_functiondef('public.guard_agreement_asset()'::regprocedure) INTO d; d=replace(d,'NEW.schedule_snapshot=jsonb_build_object(''name'',d.name,''body'',d.body,''items'',d.items,''revision'',d.revision);','NEW.schedule_snapshot=jsonb_build_object(''name'',d.name,''body'',CASE WHEN ''client''=ANY(d.audience) THEN d.body ELSE '''' END,''items'',(SELECT coalesce(jsonb_agg(v),''[]''::jsonb) FROM unnest(d.items) WITH ORDINALITY t(v,n) WHERE ''client''=ANY(d.audience) AND coalesce(d.field_specs->(n::integer-1)->>''audience'',''both'')<>''technician''),''revision'',d.revision);'); EXECUTE d; END $$;